div.script:
(function() {
    var panel = document.getElementById('lms-viewer-panel');
    var titleEl = document.getElementById('lms-viewer-title');
    var videoContainer = document.getElementById('lms-video-container');
    var videoIframe = document.getElementById('lms-video-iframe');
    var docContainer = document.getElementById('lms-doc-container');
    var docIframe = document.getElementById('lms-doc-iframe');
    var closeBtn = document.getElementById('lms-viewer-close');
    function showVideo(embedUrl, title) {
        if (!embedUrl) return;
        videoIframe.src = embedUrl;
        docIframe.src = '';
        docContainer.style.display = 'none';
        videoContainer.style.display = 'block';
        if (titleEl) titleEl.textContent = title || 'Video';
        if (panel) panel.style.display = 'block';
        panel.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
    function showDoc(viewUrl, title) {
        if (!viewUrl) return;
        docIframe.src = viewUrl;
        videoIframe.src = '';
        videoContainer.style.display = 'none';
        docContainer.style.display = 'block';
        if (titleEl) titleEl.textContent = title || 'Document';
        if (panel) panel.style.display = 'block';
        panel.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
    function closeViewer() {
        videoIframe.src = '';
        docIframe.src = '';
        videoContainer.style.display = 'none';
        docContainer.style.display = 'none';
        if (panel) panel.style.display = 'none';
    }
    if (closeBtn) closeBtn.addEventListener('click', closeViewer);
    document.querySelectorAll('.lms-open-video').forEach(function(btn) {
        btn.addEventListener('click', function(e) { e.preventDefault(); showVideo(btn.getAttribute('data-video-embed'), btn.getAttribute('data-title')); });
    });
    document.querySelectorAll('.lms-open-doc').forEach(function(btn) {
        btn.addEventListener('click', function(e) { e.preventDefault(); showDoc(btn.getAttribute('data-doc-view'), btn.getAttribute('data-title')); });
    });
    document.querySelectorAll('.lms-open-item').forEach(function(a) {
        a.addEventListener('click', function(e) {
            var type = a.getAttribute('data-type');
            var videoUrl = a.getAttribute('data-video-embed');
            var docUrl = a.getAttribute('data-doc-view');
            var title = a.getAttribute('data-title') || '';
            if (type === 'video' && videoUrl) { e.preventDefault(); showVideo(videoUrl, title); }
            else if ((type === 'document' || type === 'image' || type === 'update' || type === 'video') && docUrl) { e.preventDefault(); showDoc(docUrl, title); }
            else { var id = a.getAttribute('data-material-id'); if (id) document.getElementById('material-' + id) && document.getElementById('material-' + id).scrollIntoView({ behavior: 'smooth' }); }
        });
    });
    if (window.location.hash) {
        var id = window.location.hash.replace('#material-', '');
        var row = document.getElementById('material-' + id);
        if (row) {
            var t = row.getAttribute('data-type');
            var v = row.getAttribute('data-video-embed');
            var d = row.getAttribute('data-doc-view');
            var tit = row.getAttribute('data-title');
            if (t === 'video' && v) showVideo(v, tit);
            else if (d) showDoc(d, tit);
            else row.scrollIntoView({ behavior: 'smooth' });
        }
    }
})();
